H.background();
const cx = H.W*0.5, cy = H.H*0.52, R = 160;
let d = P.d + 6*Math.sin(t*0.6);
const maxd = R - 4;
if (d > maxd) d = maxd; if (d < -maxd) d = -maxd;
const half = Math.sqrt(Math.max(0, R*R - d*d));
const Mx = cx, My = cy + d;
const Lx = cx - half, Ly = cy + d;
const Rx = cx + half, Ry = cy + d;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 4, { fill: H.colors.sub });
H.line(Lx, Ly, Rx, Ry, { color: H.colors.accent2, width: 3 });
H.circle(Lx, Ly, 5, { fill: H.colors.yellow });
H.circle(Rx, Ry, 5, { fill: H.colors.yellow });
H.line(cx, cy, Mx, My, { color: H.colors.accent, width: 2.5 });
H.circle(Mx, My, 5, { fill: H.colors.good });
const s = 14;
const sgn = d >= 0 ? 1 : -1;
H.path([[Mx - s, My - sgn*s],[Mx - s, My],[Mx, My]], { color: H.colors.good, width: 2 });
function tick(ax,ay,bx,by){ const mx=(ax+bx)/2, my=(ay+by)/2; H.line(mx, my-7, mx, my+7, { color: H.colors.good, width: 2 }); }
tick(Lx,Ly,Mx,My); tick(Mx,My,Rx,Ry);
H.text("A perpendicular radius bisects the chord", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Blue radius hits the chord at 90 deg; the two green halves are equal.", 24, 52, { color: H.colors.sub, size: 13 });
